import React from "react";
import AddPassword from "./components/AddPassword";
import PasswordProvider from './store/PasswordProvider';



const App=()=>{
    return(
        <div>
            <div className="app">
            <h2>Password Keeper </h2>
           <PasswordProvider>
            <span>Total passwords: {}</span>
         <AddPassword></AddPassword>
         </PasswordProvider> 
        </div>
        </div>
    )
}
export default App;
